/// `Tile::lightBlock[id]` — how much light the block absorbs (255 = fully opaque).
#[inline]
pub fn light_block(id: u8) -> u8 {
    LIGHT_BLOCK[id as usize]
}
/// `Tile::lightEmission[id]`
#[inline]
pub fn light_emission(id: u8) -> u8 {
    LIGHT_EMISSION[id as usize]
}
/// `Tile::solid[id]` (the `isSolidRender` flag given to the constructor).
#[inline]
pub fn is_solid_render(id: u8) -> bool {
    SOLID_RENDER[id as usize]
}
/// `Tile::transculent[id]` (`!material->blocksLight()`).
#[inline]
pub fn is_translucent(id: u8) -> bool {
    TRANSLUCENT[id as usize]
}
/// `Tile::propagate[id]` — lighting reads the brightest neighbour instead of the block itself.
#[inline]
pub fn propagates(id: u8) -> bool {
    PROPAGATE[id as usize]
}
/// Whether a tile object exists for `id` (`Tile::tiles[id] != nullptr`; id 0 is false).
#[inline]
pub fn is_registered(id: u8) -> bool {
    REGISTERED[id as usize]
}
/// `Tile::tiles[id]->material`, or air for 0 / unknown ids (`Level::getMaterial`).
#[inline]
pub fn material(id: u8) -> Material {
    MATERIAL[id as usize]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::tile_ids as t;

    #[test]
    fn well_known_opacity() {
        assert_eq!(light_block(t::STONE), 255);
        assert_eq!(light_block(0), 0);
        assert_eq!(light_block(t::GLASS), 0);
        assert_eq!(light_block(t::LEAVES), 1);
        assert_eq!(light_block(t::WATER), 3);
        assert_eq!(light_block(t::CALM_WATER), 3);
        assert_eq!(light_block(t::ICE), 3);
        assert_eq!(light_block(t::LAVA), 255);
        assert_eq!(light_block(t::FARMLAND), 255);
        assert_eq!(light_block(t::TORCH), 0);
        assert_eq!(light_block(t::TALLGRASS), 0);
        assert_eq!(light_block(t::TREE_TRUNK), 255);
        assert_eq!(light_block(t::CACTUS), 0);
    }

    #[test]
    fn well_known_emission_and_materials() {
        assert_eq!(light_emission(t::LAVA), 15);
        assert_eq!(light_emission(t::TORCH), 14);
        assert_eq!(light_emission(t::GLOWSTONE), 15);
        assert_eq!(light_emission(t::MUSHROOM_BROWN), 1);
        assert_eq!(light_emission(t::FURNACE_LIT), 13);
        assert_eq!(light_emission(t::STONE), 0);
        assert_eq!(material(t::STONE), Material::Stone);
        assert_eq!(material(t::TREE_TRUNK), Material::Wood);
        assert_eq!(material(t::LEAVES), Material::Leaves);
        assert_eq!(material(t::CACTUS), Material::Cactus);
        assert_eq!(material(0), Material::Air);
    }

    #[test]
    fn propagation_flags() {
        assert!(!propagates(t::LEAVES)); // lightBlock 1 and material blocks light
        assert!(!propagates(t::STONE));
        assert!(propagates(t::GLASS));
        assert!(!propagates(0)); // tiles[0] is null so the loop skips it
        assert!(propagates(t::FARMLAND));
    }
}
